from pathlib import Path
import hashlib,json,re,subprocess,sys
root=Path('/home/joshua/lonely-runner-formalization'); m=json.loads(Path('/tmp/astra-pass97-inputs.json').read_text()); errs=[]; count=0
def sha(b): return hashlib.sha256(b).hexdigest()
def git(*a): return subprocess.run(['git',*a],cwd=root,text=True,capture_output=True,check=False)
for p,h in m['hashes'].items():
 q=root/p
 if not q.exists() or sha(q.read_bytes())!=h: errs.append('hash '+p)
for p in m['binding_documents']:
 text=(root/p).read_text()
 for line in text.splitlines():
  cells=[x.strip() for x in line.strip().split('|')]
  if len(cells)>=3 and re.fullmatch(r'[0-9a-f]{64}',cells[-2] if cells[-1]=='' else cells[-1]):
   h=cells[-2] if cells[-1]=='' else cells[-1]; path=cells[-3] if cells[-1]=='' else cells[-2]
   path=path.strip('` ')
   if '/' in path and (not (root/path).exists() or sha((root/path).read_bytes())!=h): errs.append('binding '+path)
   count+=1
for p in m['new_text_files']:
 b=(root/p).read_bytes()
 if not b.endswith(b'\n') or any(x.rstrip(b' \t')!=x for x in b.splitlines()): errs.append('whitespace '+p)
base=m['baseline']; old=set(git('ls-tree','-r','--name-only',base,'--','LonelyRunner').stdout.splitlines()); now=set(str(x.relative_to(root)) for x in (root/'LonelyRunner').rglob('*.lean'))
if old!=now: errs.append('lean path set')
for p in old:
 if git('diff','--quiet',base,'--',p).returncode: errs.append('lean bytes '+p)
for p in ['lean-toolchain','lakefile.toml','lake-manifest.json','scripts/audit_lean_trust.py']:
 if git('diff','--quiet',base,'--',p).returncode: errs.append('pinned '+p)
if subprocess.run(['python3','scripts/validate_workflow.py'],cwd=root,capture_output=True,text=True).returncode: errs.append('workflow')
if git('diff','--check').returncode: errs.append('diff-check')
print(json.dumps({'binding_rows':count,'errors':errs},sort_keys=True));sys.exit(bool(errs))

